package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import java.util.*;import org.json.*;import org.junit.*;
public final class ProjectByteDeleteTest {
 private static final byte[] RAW={0,(byte)255,0,3};private static final String PATH="asset.bin",CHECKOUT="11111111-1111-1111-1111-111111111111",OP="22222222-2222-2222-2222-222222222222";
 private JSONObject edit()throws Exception{return new JSONObject().put("action","delete_bytes").put("path",PATH).put("expectedHash",ProjectSources.sha256(RAW));}
 private JSONObject snapshot(Map<String,byte[]> all)throws Exception{JSONArray files=new JSONArray();for(var entry:all.entrySet())files.put(new JSONObject().put("path",entry.getKey()).put("binary",true).put("contentBase64",Base64.getEncoder().encodeToString(entry.getValue())));return new JSONObject().put("files",files);}
 private JSONObject row()throws Exception{return ProjectExactPatch.prepare(snapshot(Map.of(PATH,RAW)),new JSONArray().put(edit())).getJSONObject(0);}
 private JSONObject receipt(String status,String state)throws Exception{return new JSONObject().put("status",status).put("receiptReceived",!status.equals("unknown")).put("files",new JSONArray().put(new JSONObject().put("path",PATH).put("state",state).put("afterHash","absent").put("actualAfterHash","absent")));}
 @Test public void explicitDeleteFreezesOriginalRawBytesAndNeverAcceptsAnAfterBody()throws Exception{JSONObject row=row();assertEquals("delete",row.getString("action"));assertEquals("forward",row.getString("deleteDirection"));assertArrayEquals(RAW,ProjectExactPatch.payloadBytes(row,true));assertArrayEquals(new byte[0],ProjectExactPatch.payloadBytes(row,false));assertEquals("absent",row.getString("afterHash"));assertEquals(ProjectSources.sha256(RAW),row.getJSONObject("deletedSource").getString("sha256"));assertThrows(SecurityException.class,()->ProjectByteDelete.validated(new JSONObject(row.toString()).put("contentBase64","AQ==").put("afterBytes",1)));}
 @Test public void missingWrongHashOversizedAndModelBodyAreRejectedBeforeAPlanExists()throws Exception{assertThrows(SecurityException.class,()->ProjectByteDelete.prepare(Map.of(),edit()));assertThrows(SecurityException.class,()->ProjectByteDelete.prepare(Map.of(PATH,RAW),edit().put("expectedHash","0".repeat(64))));for(String field:new String[]{"content","contentBase64","beforeContentBase64","recursive"})assertThrows(IllegalArgumentException.class,()->ProjectByteDelete.prepare(Map.of(PATH,RAW),edit().put(field,"never")));byte[] huge=new byte[ProjectExactPatch.MAX_TEXT_BYTES+1];assertThrows(IllegalArgumentException.class,()->ProjectByteDelete.prepare(Map.of(PATH,huge),edit().put("expectedHash",ProjectSources.sha256(huge))));}
 @Test public void onlySettledAppliedDeletionCanProduceANewConditionalRestoreOfTheOriginalPrivateBeforeBytes()throws Exception{JSONArray original=new JSONArray().put(row());JSONArray restored=ProjectExactPatch.reverse(snapshot(Map.of()),original,receipt("completed","applied"),OP);JSONObject file=restored.getJSONObject(0);assertEquals("create",file.getString("action"));assertEquals("restore",file.getString("deleteDirection"));assertEquals("absent",file.getString("expectedHash"));assertEquals(OP,file.getString("revertsOperationId"));assertArrayEquals(RAW,ProjectExactPatch.payloadBytes(file,false));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of(PATH,new byte[]{9})),original,receipt("completed","applied"),OP));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of()),original,receipt("unknown","unknown"),OP));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of()),original,receipt("failed","failed"),OP));assertThrows(SecurityException.class,()->ProjectByteDelete.reverse(file,OP));}
 @Test public void manifestBindingAndRestoreAbsenceCannotBeReplacedBySelfAssertedHashes()throws Exception{JSONObject row=row(),source=new JSONObject().put("path",PATH).put("sha256",ProjectSources.sha256(RAW)).put("bytes",RAW.length),core=new JSONObject().put("intent","patch").put("checkoutId",CHECKOUT).put("sourceDigest","a".repeat(64)).put("sourceManifest",new JSONArray().put(source)),payload=new JSONObject().put("checkoutId",CHECKOUT).put("expectedSourceDigest","a".repeat(64)),step=new JSONObject().put("localCommand","patchFiles").put("payload",payload);ProjectByteDelete.requirePlanSource(core,step,row);assertThrows(SecurityException.class,()->ProjectByteDelete.requirePlanSource(new JSONObject(core.toString()).put("sourceManifest",new JSONArray().put(new JSONObject(source.toString()).put("sha256","0".repeat(64)))),step,row));JSONObject restore=ProjectByteDelete.reverse(row,OP);core.put("intent","revert_operation").put("sourceManifest",new JSONArray());payload.put("revertsOperationId",OP);ProjectByteDelete.requirePlanSource(core,step,restore);core.put("sourceManifest",new JSONArray().put(source));assertThrows(SecurityException.class,()->ProjectByteDelete.requirePlanSource(core,step,restore));core.put("sourceManifest",new JSONArray());payload.put("revertsOperationId",UUID.randomUUID().toString());assertThrows(SecurityException.class,()->ProjectByteDelete.requirePlanSource(core,step,restore));}
 @Test public void malformedOrNonCanonicalPrivateRowsCannotBecomeAGeneralCreateDeleteWriter()throws Exception{JSONObject row=row();for(JSONObject forged:new JSONObject[]{new JSONObject(row.toString()).put("path","different"),new JSONObject(row.toString()).put("beforeContentBase64",row.getString("beforeContentBase64").replace("=","")),new JSONObject(row.toString()).put("beforeBytes",1),new JSONObject(row.toString()).put("unexpected","field"),new JSONObject(row.toString()).put("deleteDirection","arbitrary")})assertThrows(Exception.class,()->ProjectByteDelete.validated(forged));assertThrows(IllegalArgumentException.class,()->ProjectExactPatch.prepare(snapshot(Map.of(PATH,RAW)),new JSONArray().put(edit()).put(edit().put("path","other"))));}
 @Test public void emptySourceStillHasARealShaAndLegacyUtf8DeletionRemainsUnchanged()throws Exception{JSONObject empty=ProjectByteDelete.prepare(Map.of(PATH,new byte[0]),edit().put("expectedHash",ProjectSources.sha256(new byte[0])));assertEquals(ProjectSources.sha256(new byte[0]),empty.getString("expectedHash"));assertEquals("absent",empty.getString("afterHash"));assertArrayEquals(new byte[0],ProjectExactPatch.payloadBytes(empty,true));JSONObject textSnapshot=new JSONObject().put("files",new JSONArray().put(new JSONObject().put("path","text.txt").put("content","before")));JSONObject old=ProjectExactPatch.prepare(textSnapshot,new JSONArray().put(new JSONObject().put("action","delete").put("path","text.txt").put("expectedHash",ProjectSources.sha256("before".getBytes(java.nio.charset.StandardCharsets.UTF_8))))).getJSONObject(0);assertFalse(old.has("encoding"));assertEquals("before",old.getString("beforeContent"));assertEquals("",old.getString("content"));}
}
